import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  if (tabs.length === 0) {
    return null;
  }

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  const activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
  const last = tabs.length - 1;

  const activate = (index: number) => {
    const tab = tabs[index];
    if (tab === undefined) {
      return;
    }
    buttonRefs.current[index]?.focus();
    onSelect(tab.id);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    let next: number;
    switch (event.key) {
      case "ArrowRight":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }
    event.preventDefault();
    activate(next);
  };

  const panelId = `${baseId}-panel`;
  const tabId = (index: number) => `${baseId}-tab-${index}`;

  return (
    <div className="tab-strip">
      <div className="tab-strip__list" role="tablist">
        {tabs.map((tab, index) => {
          const isSelected = index === activeIndex;
          return (
            <button
              key={tab.id}
              ref={(element) => {
                buttonRefs.current[index] = element;
              }}
              id={tabId(index)}
              type="button"
              role="tab"
              className="tab-strip__tab"
              aria-selected={isSelected}
              aria-controls={panelId}
              tabIndex={isSelected ? 0 : -1}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>
      <div
        id={panelId}
        role="tabpanel"
        className="tab-strip__panel"
        aria-labelledby={tabId(activeIndex)}
        tabIndex={0}
      >
        {children}
      </div>
    </div>
  );
}
