.tab-strip__list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  border-bottom: 1px solid var(--hair);
}

.tab-strip__tab {
  position: relative;
  padding: 0.6rem 0.9rem;
  border: 0;
  border-radius: 0;
  background: none;
  color: var(--muted);
  font: inherit;
  font-size: clamp(0.9rem, 0.85rem + 0.3vw, 1.1rem);
  cursor: pointer;
  transition: color 150ms ease, background-color 150ms ease;
}

.tab-strip__tab:hover {
  color: var(--ink);
  background-color: var(--myelin-wash);
}

.tab-strip__tab[aria-selected="true"] {
  color: var(--ink);
  font-weight: 700;
}

.tab-strip__tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  left: 0.5rem;
  right: 0.5rem;
  bottom: -1px;
  height: 3px;
  border-radius: 999px;
  background-color: var(--myelin);
}

.tab-strip__panel {
  color: var(--ink);
}

:root[data-motion="reduce"] .tab-strip__tab {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab {
    transition: none;
  }
}
